// Cross-validation: the JavaScript that the demos run is checked against test vectors generated by the Python
// reference implementation (python/src/bitcomm, via scripts/gen_vectors.py -> test/vectors.json).
// If the two implementations ever disagree, one of these tests fails.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { stuff, destuff, frame, unframe, BitStuffingError } from '../lib/bitstuff.mjs';
import { runStopAndWait } from '../lib/stopwait.mjs';

const vectors = JSON.parse(readFileSync(new URL('./vectors.json', import.meta.url), 'utf8'));
const checked = {}; // how many vectors of each kind this suite compared
const tally = (name, n = 1) => { checked[name] = (checked[name] ?? 0) + n; };

test('vector file was written by the Python generator', () => {
  assert.equal(vectors.format, 1);
  assert.equal(vectors.generator, 'scripts/gen_vectors.py');
  assert.ok(vectors.counts.total >= 2200);
});

test('stuffing: every bit string up to 10 bits (exhaustive) matches Python', () => {
  assert.equal(vectors.stuff_exhaustive.length, 2 ** 11 - 1);
  for (const [data, stuffed] of vectors.stuff_exhaustive) {
    assert.equal(stuff(data).output, stuffed, `stuff(${data})`);
    assert.equal(destuff(stuffed).output, data, `destuff(${stuffed})`);
    tally('stuff_exhaustive');
  }
});

test('stuffing: seeded random longer strings with long runs of 1s match Python', () => {
  for (const [data, stuffed] of vectors.stuff_random) {
    assert.equal(stuff(data).output, stuffed, `stuff(${data})`);
    assert.equal(destuff(stuffed).output, data, `destuff(${stuffed})`);
    tally('stuff_random');
  }
});

test('stuffing: positions of inserted zeros and the step-by-step trace match Python', () => {
  for (const c of vectors.stuff_cases) {
    const r = stuff(c.input);
    assert.equal(r.output, c.output);
    assert.deepEqual(r.inserted, c.inserted);
    assert.deepEqual(r.steps, c.steps);
    tally('stuff_cases');
  }
});

test('destuffing: positions of removed zeros and the trace match Python', () => {
  for (const c of vectors.destuff_cases) {
    const r = destuff(c.input);
    assert.equal(r.output, c.output);
    assert.deepEqual(r.removed, c.removed);
    assert.deepEqual(r.steps, c.steps);
    tally('destuff_cases');
  }
});

test('errors: same message and position as Python for corrupted and invalid input', () => {
  for (const c of [...vectors.destuff_errors, ...vectors.invalid_input]) {
    const fn = c.op === 'destuff' ? destuff : stuff;
    assert.throws(
      () => fn(c.input),
      (error) => {
        assert.ok(error instanceof BitStuffingError);
        assert.equal(error.message, c.message);
        assert.equal(error.position, c.position);
        return true;
      },
      `${c.op}(${JSON.stringify(c.input)})`,
    );
    tally(c.op === 'destuff' && vectors.destuff_errors.includes(c) ? 'destuff_errors' : 'invalid_input');
  }
});

test('frames: frame() and unframe() match Python, and bad frames fail the same way', () => {
  for (const c of vectors.frames) {
    assert.equal(frame(c.data), c.framed);
    assert.equal(unframe(c.framed), c.data);
    tally('frames');
  }
  for (const c of vectors.unframe_errors) {
    assert.throws(
      () => unframe(c.input),
      (error) => {
        assert.ok(error instanceof BitStuffingError);
        assert.equal(error.message, c.message);
        assert.equal(error.position, c.position);
        return true;
      },
      `unframe(${JSON.stringify(c.input)})`,
    );
    tally('unframe_errors');
  }
});

test('stop-and-wait: replaying Python\'s random draws gives the same log and summary', async () => {
  for (const c of vectors.arq) {
    let next = 0;
    const log = [];
    const summary = await runStopAndWait({
      frames: c.frames,
      timeoutSec: c.timeoutSec,
      lossRate: c.lossRate,
      random: () => {
        assert.ok(next < c.draws.length, `${c.name}: JavaScript asked for more random numbers than Python used`);
        return c.draws[next++];
      },
      sleep: async () => {},
      onLog: (entry) => log.push(entry),
    });
    assert.deepEqual(log, c.log, c.name);
    assert.deepEqual(summary, c.summary, c.name);
    assert.equal(next, c.draws.length, `${c.name}: random numbers left over`);
    tally('arq');
  }
});

test('every vector the JavaScript can check was checked (CRC vectors are Python-only)', () => {
  const counts = vectors.counts;
  const expected = counts.total - counts.crc_bits - counts.crc_register;
  const total = Object.values(checked).reduce((a, b) => a + b, 0);
  for (const key of Object.keys(checked)) assert.equal(checked[key], counts[key], key);
  assert.equal(total, expected);
  console.log(`# cross-validated against Python: ${total} vectors (${JSON.stringify(checked)})`);
});
